// === Tab: mySketch ===
/** 
For "Balls" 🧆 #WCCChallenge

A generative study of balance, weight, and structural instability. 
Spheres accumulate across illuminated beams, shifting equilibrium and triggering moments of cascading motion.

Click to drop a new weighted ball.
Heavy imbalance tips beams and balls slide/fall off.
Press R to reset.

**/

let beams = [];
let balls = [];

const BEAM_COUNT = 6;
const MAX_BALLS = 55;

function setup() {
  createCanvas(windowWidth, windowHeight);
  colorMode(HSB, 360, 100, 100, 100);
  strokeCap(ROUND);
  // textFont("monospace");
  resetSketch();
}

function resetSketch() {
  beams = [];
  balls = [];

  let margin = 130;

  for (let i = 0; i < BEAM_COUNT; i++) {
    let y = map(i, 0, BEAM_COUNT - 1, margin, height - margin);

    beams.push({
      x1: width * 0.16,
      x2: width * 0.84,
      y,
      angle: random(-0.035, 0.035),
      targetAngle: 0,
      stress: 0,
      overloaded: false,
      collapse: 0
    });
  }

  for (let i = 0; i < 10; i++) {
    addBall(
      random(width * 0.24, width * 0.76),
      random(height * 0.12, height * 0.82)
    );
  }
}

function draw() {
  background(232, 70, 5);

  drawGrid();

  updateBalls();
  updateBeams();

  drawBeamGlow();
  drawBeams();
  drawBalls();
}

function addBall(x, y) {
  if (balls.length > MAX_BALLS) balls.shift();

  let r = random(11, 34);
  let mass = map(r, 11, 34, 0.7, 3.8);

  balls.push({
    x,
    y,
    vx: random(-0.35, 0.35),
    vy: random(-0.2, 0.1),
    r,
    mass,
    hue: random([42, 50, 190, 205, 220, 28]),
    beamIndex: floor(random(beams.length)),
    state: "falling"
  });
}

function updateBalls() {
  for (let b of balls) {
    let beam = beams[b.beamIndex];
    if (!beam) continue;

    let beamY = beamPointY(beam, b.x);
    let slopeForce = sin(beam.angle) * b.mass * 0.18;

    if (b.state === "falling") {
      b.vy += 0.16 * b.mass;
      b.x += b.vx;
      b.y += b.vy;

      if (b.y + b.r >= beamY && b.x > beam.x1 && b.x < beam.x2) {
        b.y = beamY - b.r;
        b.vy *= -0.16;
        b.vx *= 0.68;

        if (abs(b.vy) < 0.6) {
          b.state = "settled";
        }
      }
    }

    else if (b.state === "settled") {
      b.vx += slopeForce;
      b.vx *= 0.94;

      b.x += b.vx;
      b.y = lerp(b.y, beamPointY(beam, b.x) - b.r, 0.22);

      if (beam.overloaded || abs(beam.angle) > 0.22) {
        b.state = "sliding";
      }
    }

    else if (b.state === "sliding") {
      b.vx += slopeForce * 1.7;
      b.vy += 0.04;

      b.x += b.vx;
      b.y = beamPointY(beam, b.x) - b.r;

      if (b.x < beam.x1 + b.r || b.x > beam.x2 - b.r) {
        b.state = "fallen";
        b.vy = random(1.5, 3.5);
      }
    }

    else if (b.state === "fallen") {
      b.vy += 0.22;
      b.x += b.vx;
      b.y += b.vy;
    }
  }

  balls = balls.filter(b => b.y < height + 140);
}

function updateBeams() {
  for (let i = 0; i < beams.length; i++) {
    var beam = beams[i];

    let torque = 0;
    let stress = 0;
    let leftWeight = 0;
    let rightWeight = 0;

    for (let b of balls) {
      if (b.beamIndex !== i) continue;
      if (b.state === "fallen") continue;

      let center = (beam.x1 + beam.x2) * 0.5;
      let side = (b.x - center) / ((beam.x2 - beam.x1) * 0.5);

      torque += side * b.mass * 0.045;
      stress += b.mass;

      if (side < 0) leftWeight += b.mass;
      else rightWeight += b.mass;
    }

    let imbalance = abs(leftWeight - rightWeight);

    beam.overloaded = stress > 15 || imbalance > 8.5;

    if (beam.overloaded) {
      beam.collapse += 0.006;
    } else {
      beam.collapse *= 0.96;
    }

    let direction = torque === 0 ? 1 : Math.sign(torque);

    beam.targetAngle = constrain(
      torque + beam.collapse * direction,
      -0.42,
      0.42
    );

    beam.angle = lerp(beam.angle, beam.targetAngle, 0.055);
    beam.stress = lerp(beam.stress, stress, 0.08);
  }
}

function drawBeamGlow() {
  blendMode(ADD);

  for (let beam of beams) {
    let cx = (beam.x1 + beam.x2) * 0.5;
    let len = beam.x2 - beam.x1;

    push();
    translate(cx, beam.y);
    rotate(beam.angle);

    stroke(198, 90, 100, 16);
    strokeWeight(13);
    line(-len / 2, 0, len / 2, 0);

    stroke(215, 95, 100, 10);
    strokeWeight(24);
    line(-len / 2, 0, len / 2, 0);

    if (beam.overloaded) {
      stroke(28, 100, 100, 35);
      strokeWeight(28);
      line(-len / 2, 0, len / 2, 0);

      stroke(325, 100, 100, 28);
      strokeWeight(18);
      line(-len / 2, 0, len / 2, 0);
    }

    pop();
  }

  blendMode(BLEND);
}

function drawBeams() {
  for (let beam of beams) {
    var cx = (beam.x1 + beam.x2) * 0.5;
    var len = beam.x2 - beam.x1;

    push();
    translate(cx, beam.y);
    rotate(beam.angle);

    if (beam.overloaded) {
      stroke(18, 95, 100, 45);
      strokeWeight(18);
      line(-len / 2, 0, len / 2, 0);

      stroke(325, 90, 100, 65);
      strokeWeight(9);
      line(-len / 2, 0, len / 2, 0);
    }

    stroke(205, 90, 100, 65);
    strokeWeight(7);
    line(-len / 2, 0, len / 2, 0);

    stroke(190, 35, 100, 96);
    strokeWeight(2.4);
    line(-len / 2, 0, len / 2, 0);

    stroke(140, 95, 100, 35);
    strokeWeight(1);

    for (let x = -len / 2; x <= len / 2; x += 36) {
      line(x, -10, x, 10);
    }

    pop();
  }
}

function drawBalls() {
  blendMode(ADD);

  for (let b of balls) {
    let heavy = map(b.mass, 0.7, 3.8, 0, 1);

    noStroke();

    fill(b.hue, 100, 100, 16);
    circle(b.x, b.y, b.r * 3.4);

    fill(b.hue, 95, 100, 20);
    circle(b.x, b.y, b.r * 2.65);

    if (b.mass > 2.6) {
      fill(45, 100, 100, 22);
      circle(b.x, b.y, b.r * 3.9);
    }
  }

  blendMode(BLEND);

  for (let b of balls) {
    var heavy = map(b.mass, 0.7, 3.8, 0, 1);

    stroke(0, 0, 100, 75);
    strokeWeight(1.4);

    fill(
      b.hue,
      90,
      72 + heavy * 25,
      96
    );

    circle(b.x, b.y, b.r * 2);

    noStroke();

    fill(0, 0, 100, 55);
    circle(
      b.x - b.r * 0.36,
      b.y - b.r * 0.38,
      b.r * 0.38
    );

    fill(0, 0, 100, 88);
    // textAlign(CENTER, CENTER);
    // textSize(constrain(b.r * 0.42, 8, 14));
    // text(nf(b.mass, 1, 1), b.x, b.y);
  }
}

function beamPointY(beam, x) {
  var cx = (beam.x1 + beam.x2) * 0.5;
  return beam.y + sin(beam.angle) * (x - cx);
}

function drawGrid() {
  stroke(245, 55, 100, 8);
  strokeWeight(1);

  for (let x = 0; x < width; x += 42) {
    line(x, 0, x, height);
  }

  for (let y = 0; y < height; y += 42) {
    line(0, y, width, y);
  }

  stroke(190, 100, 100, 16);
  line(0, height * 0.5, width, height * 0.5);
}

function mousePressed() {
  addBall((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
}

function keyPressed() {
  if (key === "r" || key === "R") {
    resetSketch();
  }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
  resetSketch();
}

